<?php
require __DIR__.'/api/auth.php';$u=require_user();$isAdmin=$u['role']==='admin';$statuses=['received'=>'Received / Otrzymano','reviewed'=>'Under review / W trakcie','response_ready'=>'Response available / Jest odpowiedź','closed'=>'Closed / Zakończono'];
if($_SERVER['REQUEST_METHOD']==='POST'&&$isAdmin){check_csrf();$rid=(int)($_POST['registration_id']??0);$status=(string)($_POST['status']??'received');$reply=trim((string)($_POST['reply']??''));if(isset($statuses[$status])){$s=db()->prepare('UPDATE registrations SET portal_status=? WHERE id=?');$s->execute([$status,$rid]);if($reply!==''){$s=db()->prepare('INSERT INTO registration_messages(registration_id,author_user_id,message) VALUES(?,?,?)');$s->execute([$rid,$u['id'],$reply]);db()->prepare("UPDATE registrations SET portal_status='response_ready' WHERE id=?")->execute([$rid]);$s=db()->prepare('SELECT email FROM registrations WHERE id=?');$s->execute([$rid]);$mail=$s->fetchColumn();if($mail)@mail($mail,'SPECTECHNOLOGY — new response',"A new response is available in your account:\nhttps://spectechnology.pl/login.php","From: office@spectechnology.pl\r\nContent-Type: text/plain; charset=UTF-8",'-f office@spectechnology.pl');}header('Location: /dashboard.php');exit;}}
$sql=$isAdmin?'SELECT r.*,(SELECT COUNT(*) FROM registration_files f WHERE f.registration_id=r.id) file_count,(SELECT COUNT(*) FROM registration_messages m WHERE m.registration_id=r.id) message_count FROM registrations r ORDER BY r.created_at DESC':'SELECT r.*,(SELECT COUNT(*) FROM registration_files f WHERE f.registration_id=r.id) file_count,(SELECT COUNT(*) FROM registration_messages m WHERE m.registration_id=r.id) message_count FROM registrations r WHERE r.user_id=? ORDER BY r.created_at DESC';$s=db()->prepare($sql);$s->execute($isAdmin?[]:[$u['id']]);$regs=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portal — SPECTECHNOLOGY</title><link rel="stylesheet" href="/assets/site-v13.css"><link rel="stylesheet" href="/assets/portal.css"></head><body class="portal"><header class="portal-header"><a href="/"><img src="/noBgColor-dark.png" alt="SPECTECHNOLOGY"></a><div><b><?=e($u['username'])?></b> · <a href="/logout.php">Sign out / Wyloguj</a></div></header><main class="portal-main"><p class="eyebrow"><?=$isAdmin?'ADMIN PANEL':'MY ACCOUNT'?></p><h1><?=$isAdmin?'Applications / Zgłoszenia':'My applications / Moje zgłoszenia'?></h1><?php if($isAdmin):?><div class="view-switch" aria-label="Display mode"><button type="button" data-admin-view="cards" class="active">▦ Cards</button><button type="button" data-admin-view="table">☷ Table</button></div><div class="admin-table-head"><span>ID / Date</span><span>Email</span><span>Status</span><span>Files</span><span>Messages</span><span></span></div><?php endif?><?php if(!$regs):?><p>No applications yet.</p><?php endif?><?php foreach($regs as $r):?><article class="application" id="application-<?=e((string)$r['id'])?>"><div class="admin-table-row"><span>#<?=e((string)$r['id'])?> · <?=e(substr((string)$r['created_at'],0,10))?></span><span><?=e($r['email'])?></span><span><?=e($statuses[$r['portal_status']]??$r['portal_status'])?></span><span><?=e((string)($r['file_count']??0))?></span><span><?=e((string)($r['message_count']??0))?></span><button type="button" class="table-expand" aria-expanded="false">Open</button></div><div class="application-body"><div class="application-head"><div><small>#<?=e((string)$r['id'])?> · <?=e($r['created_at'])?></small><h2><?=e($r['company']?:$r['name']?:$r['email'])?></h2><p><?=e($r['email'])?> · <?=e($r['country'])?> · <?=e($r['role'])?></p></div><span class="status status-<?=e($r['portal_status'])?>"><?=e($statuses[$r['portal_status']]??$r['portal_status'])?></span></div><div class="message"><?=nl2br(e($r['details']))?></div><?php $fs=db()->prepare('SELECT * FROM registration_files WHERE registration_id=?');$fs->execute([$r['id']]);$files=$fs->fetchAll();if($files):?><h3>Documents / Dokumenty</h3><ul><?php foreach($files as $f):?><li class="portal-file"><?php if(str_starts_with((string)$f['mime_type'],'image/')):?><a href="/download.php?id=<?=$f['id']?>" class="file-preview"><img src="/download.php?id=<?=$f['id']?>&inline=1" alt="<?=e($f['original_name'])?>"></a><?php endif?><span><?=e($f['original_name'])?></span><a href="/download.php?id=<?=$f['id']?>">Download / Pobierz</a></li><?php endforeach?></ul><?php endif?><?php $ms=db()->prepare('SELECT m.*,u.username FROM registration_messages m LEFT JOIN users u ON u.id=m.author_user_id WHERE m.registration_id=? ORDER BY m.created_at');$ms->execute([$r['id']]);foreach($ms as $m):?><div class="reply"><b><?=e($m['username']??'SPECTECHNOLOGY')?>:</b> <?=nl2br(e($m['message']))?></div><?php endforeach?><?php if($isAdmin):?><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="registration_id" value="<?=$r['id']?>"><label>Status<select name="status"><?php foreach($statuses as $k=>$v):?><option value="<?=$k?>" <?=$r['portal_status']===$k?'selected':''?>><?=e($v)?></option><?php endforeach?></select></label><label>Response / Odpowiedź<textarea name="reply"></textarea></label><button class="primary">Save / Zapisz</button></form><?php endif?></div></article><?php endforeach?></main><?php if($isAdmin):?><script src="/assets/admin.js" defer></script><?php endif?></body></html>
